/*
 * prog54_topo_sort – reconstructed from the obfuscated binary.
 *
 * Expected command‑line format:
 *
 *   prog54_topo_sort N M u1 v1 u2 v2 ... uM vM
 *
 *   N – number of vertices (1 ≤ N ≤ 8)
 *   M – number of directed edges (0 ≤ M ≤ 8)
 *   (ui, vi) – directed edge ui → vi, 0 ≤ ui,vi < N
 *
 * Behaviour
 * ----------
 * * If any argument is missing, malformed, out of range, or if N or M
 *   exceed 8, the program prints
 *
 *       INVALID_INPUT
 *
 *   (followed by a newline) and exits with status 1.
 *
 * * Otherwise it attempts a topological sort (Kahn's algorithm).
 *   Vertices are printed as decimal numbers separated by a single space.
 *
 * * If the graph contains a cycle the program prints
 *
 *       CYCLE
 *
 *   followed by **two** newline characters (the original binary does
 *   `puts("CYCLE")` then `putchar('\n')`) and exits with status 1.
 *
 * * On success it prints the ordering and a final newline, then exits
 *   with status 0.
 *
 * The implementation below reproduces exactly the observable behaviour
 * while being clean, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8          /* maximum number of vertices */
#define MAXE 8          /* maximum number of edges */

int main(int argc, char *argv[])
{
    long n, m;                 /* number of vertices and edges */
    char *endptr;
    int i, u, v;
    int adj[MAXV][MAXV] = {{0}};   /* adjacency matrix */
    int indeg[MAXV] = {0};         /* indegree counters */
    int done[MAXV] = {0};          /* kept for parity with the original binary */
    int q[MAXV];                  /* simple queue for Kahn's algorithm */
    int qhead = 0, qtail = 0;
    int printed = 0;

    /* -------------------------------------------------------------
       1. Basic argument count check.
       ------------------------------------------------------------- */
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* -------------------------------------------------------------
       2. Parse N and M.
       ------------------------------------------------------------- */
    n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n <= 0 || n > MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }

    m = strtol(argv[2], &endptr, 10);
    if (*endptr != '\0' || m < 0 || m > MAXE) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* -------------------------------------------------------------
       3. Verify that the exact number of edge arguments is present.
       ------------------------------------------------------------- */
    if (argc != 3 + 2 * m) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* -------------------------------------------------------------
       4. Read the edges, fill adjacency matrix and indegree array.
       ------------------------------------------------------------- */
    for (i = 0; i < m; ++i) {
        u = (int)strtol(argv[3 + 2 * i], &endptr, 10);
        if (*endptr != '\0' || u < 0 || u >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        v = (int)strtol(argv[4 + 2 * i], &endptr, 10);
        if (*endptr != '\0' || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }

        /* store edge u -> v (ignore duplicate edges) */
        if (!adj[u][v]) {
            adj[u][v] = 1;
            indeg[v] += 1;
        }
    }

    /* -------------------------------------------------------------
       5. Initialise queue with all vertices of indegree 0.
       ------------------------------------------------------------- */
    for (i = 0; i < n; ++i) {
        if (indeg[i] == 0) {
            q[qtail++] = i;
        }
    }

    /* -------------------------------------------------------------
       6. Kahn's algorithm – produce a topological order.
       ------------------------------------------------------------- */
    while (qhead < qtail) {
        int cur = q[qhead++];
        printf("%d", cur);
        printed++;

        if (printed < n) {
            putchar(' ');
        }

        for (i = 0; i < n; ++i) {
            if (adj[cur][i]) {
                indeg[i]--;
                if (indeg[i] == 0) {
                    q[qtail++] = i;
                }
            }
        }
    }

    /* -------------------------------------------------------------
       7. Detect a cycle.
       ------------------------------------------------------------- */
    if (printed < n) {
        puts("CYCLE");   /* adds first newline */
        putchar('\n');   /* second newline, matching the original binary */
        return 1;
    }

    /* Successful topological sort – end with a newline. */
    putchar('\n');
    return 0;
}
